class Journal:
    """Records entries at most once per ``entry_id``.

    Accepted entries contribute their values to :meth:`total` and are
    counted by :meth:`count`.  Re-applying a known entry id is a no-op
    and returns ``False``.
    """

    def __init__(self) -> None:
        self._entries: dict = {}

    def apply(self, entry_id: str, value: int) -> bool:
        """Validate and record ``value`` under ``entry_id``.

        Returns ``True`` if the entry was accepted, ``False`` if
        ``entry_id`` had already been applied (in which case nothing
        changes).

        Raises:
            ValueError: if ``entry_id`` is not a non-empty (and
                non-whitespace) ``str``, or ``value`` is not an ``int``
                (``bool`` is not accepted).
        """
        if not isinstance(entry_id, str) or entry_id.strip() == "":
            raise ValueError(
                "entry_id must be a non-empty, non-whitespace string"
            )
        if not isinstance(value, int) or isinstance(value, bool):
            raise ValueError("value must be an int (bool is not accepted)")
        if entry_id in self._entries:
            return False
        self._entries[entry_id] = value
        return True

    def total(self) -> int:
        """Return the sum of all accepted values."""
        return sum(self._entries.values())

    def count(self) -> int:
        """Return the number of accepted entries."""
        return len(self._entries)
